function DaftarTugas({ tugas }) {
  if (tugas.length === 0) {
    return <p>Belum ada tugas.</p>;
  }

  return (
    <ul>
      {tugas.map((item) => (
        <li key={item.id}>{item.judul}</li>
      ))}
    </ul>
  );
}

function FormTugas({ onTambah }) {
  const [judul, setJudul] = useState("");

  function kirim(e) {
    e.preventDefault();
    onTambah(judul);
    setJudul("");
  }

  return (
    <form onSubmit={kirim}>
      <input value={judul} onChange={(e) => setJudul(e.target.value)} />
    </form>
  );
}

